#include <stdio.h>

int main(void) {
    const char *json = "{\"Name\":\"Bob\",\"Age\":25}";
    char name[16];
    int age;
    sscanf(json, "{\"Name\":\"%15[^\"]\",\"Age\":%d}", name, &age);
