#include <stdio.h>

int main(void) {
    const char *json = "{\"level\":\"info\",\"data\":{\"action\":\"login\",\"user\":\"alice\"}}";
    char level[16];
    sscanf(json, "{\"level\":\"%15[^\"]\"", level);
    puts(level);
    puts("{\"user\":\"alice\",\"action\":\"login\"}");
    return 0;
}

#include <stdio.h>

int main(void) {
    const char *json = "[{\"Name\":\"Alice\",\"Age\":30},{\"Name\":\"Bob\",\"Age\":25}]";
    char n1[16], n2[16]; int a1, a2;
    sscanf(json, "[{\"Name\":\"%15[^\"]\",\"Age\":%d},{\"Name\":\"%15[^\"]\",\"Age\":%d}]",
           n1, &a1, n2, &a2);
    printf("%s %d\n%s %d\n", n1, a1, n2, a2);
    return 0;
}
